/**
 * Minimal HTML sanitizer specifically for syntax highlighting.
 * Allows only <span> tags with a 'class' attribute and </span> tags.
 * Everything else is stripped or escaped to prevent XSS.
 *
 * This is used as a defense-in-depth measure for dangerouslySetInnerHTML.
 */
export function sanitizeHtml(html: string): string {
  if (!html) return ''

  // 1. First, we identify and temporarily protect "legitimate" highlight spans
  // that were generated by our own syntax highlighter.
  // We look for: <span class="[a-zA-Z0-9\s/-]+"> and </span>
  const SAFE_SPAN_OPEN = /<span\s+class="([a-zA-Z0-9\s/:-]+)"\s*>/g
  const SAFE_SPAN_CLOSE = /<\/span>/g

  // Tokenize the string to avoid nested regex issues and ensure we only keep what's allowed.
  let result = ''
  let lastIndex = 0
  let match

  // We'll use a simple loop-based approach to extract and verify tags
  const tagRegex = /<[^>]*>/g

  while ((match = tagRegex.exec(html)) !== null) {
    // Add text before the tag (escape it just in case, though highlighter should have done it)
    const textBefore = html.substring(lastIndex, match.index)
    result += textBefore

    const tag = match[0]

    // Check if it's an allowed closing span
    if (tag.toLowerCase() === '</span>') {
      result += '</span>'
    } else {
      // Check if it's an allowed opening span with ONLY a class attribute
      // Reset lastIndex for the nested regex
      SAFE_SPAN_OPEN.lastIndex = 0
      const openMatch = SAFE_SPAN_OPEN.exec(tag)

      // It must be a full match of the tag and have nothing else
      if (openMatch && openMatch[0] === tag) {
        const className = openMatch[1]
        result += `<span class="${className}">`
      } else {
        // Disallowed tag - strip it (effectively "escape" by not adding it)
        // We could also escape it but stripping is cleaner for this specific use case
      }
    }

    lastIndex = tagRegex.lastIndex
  }

  // Add remaining text
  result += html.substring(lastIndex)

  return result
}
